// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address to, uint v) public {
        // Bound v to avoid overflow issues, assume to is not zero address
        v = bound(v, 0, 1e30);
        vm.assume(to != address(0));
        address[] memory tos = new address[](1);
        tos[0] = to;

        // Deploy a dummy token contract that will revert on transferFrom
        DummyToken token = new DummyToken();

        // Call transfer - this should revert in reference but not in mutant
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.transfer.selector, from, address(token), tos, v));

        // The rule: if the token reverts, the call should revert
        assertTrue(success == false, "transfer should revert when token transferFrom reverts");
    }
}

contract DummyToken {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        revert("transferFrom failed");
    }
}

